<h1>Carrinho de vendas</h1>
<form class="row g-2 mb-3"><input type="hidden" name="r" value="vendas"><div class="col-md-9"><input class="form-control" name="q" placeholder="Buscar produto por nome ou código" value="<?=htmlspecialchars($_GET['q']??'')?>"></div><div class="col-md-3"><button class="btn btn-outline-primary w-100">Buscar produtos</button></div></form>
<div class="table-responsive"><table class="table table-striped"><thead><tr><th>Código</th><th>Produto</th><th>Estoque</th><th>Preço unitário</th><th>Adicionar</th></tr></thead><tbody>
<?php foreach($produtos as $p): ?><tr><td><?=htmlspecialchars($p['cod']??'')?></td><td><?=htmlspecialchars($p['nome'])?></td><td><?=$p['quantidade']?></td><td>R$ <?=number_format((float)$p['preco_unitario'],2,',','.')?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="produto_id" value="<?=$p['id']?>"><input class="form-control" style="max-width:90px" type="number" min="1" max="<?=$p['quantidade']?>" name="quantidade" value="1"><button class="btn btn-sm btn-success" name="adicionar" <?=$p['quantidade']<1?'disabled':''?>>Adicionar</button></form></td></tr><?php endforeach; ?>
<?php if(!$produtos): ?><tr><td colspan="5">Nenhum produto encontrado.</td></tr><?php endif; ?></tbody></table></div>
<hr><h2>Itens do carrinho</h2><form method="post" action="/?r=vendas"><div class="table-responsive"><table class="table"><thead><tr><th>Produto</th><th>Preço</th><th>Quantidade</th><th>Subtotal</th><th>Ação</th></tr></thead><tbody>
<?php $total=0; foreach($carrinhoItens as $linha): $p=$linha['produto']; $id=(int)$p['id']; $q=(int)$linha['quantidade']; $sub=(float)$p['preco_unitario']*$q; $total+=$sub; ?><tr><td><?=htmlspecialchars($p['nome'])?></td><td>R$ <?=number_format((float)$p['preco_unitario'],2,',','.')?></td><td><input class="form-control" style="max-width:100px" type="number" min="0" max="<?=$p['quantidade']?>" name="qtd[<?=$id?>]" value="<?=$q?>"></td><td>R$ <?=number_format($sub,2,',','.')?></td><td><button class="btn btn-sm btn-outline-danger" name="remover" value="<?=$id?>">Remover</button></td></tr><?php endforeach; ?>
<?php if(!$carrinhoItens): ?><tr><td colspan="5">Seu carrinho está vazio.</td></tr><?php endif; ?></tbody><tfoot><tr><th colspan="3" class="text-end">Total</th><th>R$ <?=number_format($total,2,',','.')?></th><th></th></tr></tfoot></table></div><button class="btn btn-outline-primary" name="atualizar" <?=$carrinhoItens?'':'disabled'?>>Atualizar quantidades</button></form>
<form method="post" action="/?r=vendas" class="card card-body mt-3"><h5>Finalizar venda</h5><label class="form-label">Cliente (opcional)</label><select class="form-select mb-3" name="cliente_id"><option value="">Consumidor não identificado</option><?php foreach($clientes as $cliente): ?><option value="<?=$cliente['id']?>"><?=htmlspecialchars($cliente['nome'])?></option><?php endforeach; ?></select><button class="btn btn-success" name="finalizar" <?=$carrinhoItens?'':'disabled'?>>Concluir venda</button></form>
